package com.mohymods.kingdomsmp.profession;
import com.mohymods.kingdomsmp.economy.CommerceService;
import com.mohymods.kingdomsmp.placement.PlacementProtection;
import java.util.*;
import net.minecraft.server.level.*;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.network.chat.Component;
import net.neoforged.bus.api.*;
import net.neoforged.neoforge.event.entity.player.PlayerInteractEvent;
/** Explicit live supervisor and one commission purpose, never nearest-player or client-count attribution. */
public final class ApiaryJobs {
 public static final String FOREST="kingdom_smp:lumberjack/m04",REAGENTS="kingdom_smp:alchemist/j05";
 private static final String TARGET="kingdom_smp_apiary_job";
 private ApiaryJobs(){}
 public static boolean contains(String id){return FOREST.equals(id)||REAGENTS.equals(id);}
 public static boolean eligible(ServerPlayer p,String id){if(!contains(id)||!ApiaryProduction.supported()||!TreeQuestService.real(p))return false;var d=ApprovedProfessionContent.get(id);var r=CommerceService.store(p.server).professions(p.getUUID());return r.isActive(d.profession())&&r.progressBand(d.profession())==d.rank()&&!r.track(d.profession()).completedQuestIds().contains(id)&&CraftDeliveryQuests.catalog().mayAttempt(d.profession(),id,r.track(d.profession()).completedQuestIds())&&com.mohymods.kingdomsmp.contribution.ContributionService.kingdom(p.server).attainedTier()>=6&&com.mohymods.kingdomsmp.building.ConstructionService.store(p.server).projects().stream().anyMatch(q->q.phase()==com.mohymods.kingdomsmp.persistence.ConstructionStore.Phase.COMPLETE&&!q.npcDead()&&q.blueprint().toString().equals(d.profession().buildingId()));}
 public static void choose(ServerPlayer p,String id){if(!eligible(p,id))throw new IllegalStateException("This apiary commission is unavailable");ContractService.requireCounter(p,ApprovedProfessionContent.get(id).profession());p.getPersistentData().putString(TARGET,id);}
 public static void register(IEventBus bus){bus.addListener(EventPriority.LOWEST,false,PlayerInteractEvent.RightClickBlock.class,ApiaryJobs::interact);}
 private static void interact(PlayerInteractEvent.RightClickBlock event){if(!(event.getEntity() instanceof ServerPlayer p)||event.getHand()!=net.minecraft.world.InteractionHand.MAIN_HAND||!p.isShiftKeyDown()||!p.getMainHandItem().isEmpty())return;var id=p.getPersistentData().getString(TARGET);if(!contains(id)||!p.serverLevel().hasChunkAt(event.getPos()))return;var hive=p.serverLevel().getBlockEntity(event.getPos());if(hive==null||!hive.getClass().getName().equals("cy.jdkdigital.productivebees.common.block.entity.AdvancedBeehiveBlockEntity"))return;try{var site=new ApiaryEvidence.Site(p.serverLevel().dimension().location().toString(),event.getPos().asLong());var data=ApiaryJobsSavedData.get(p.server);var old=data.evidence().at(site).orElse(null);if(old!=null&&old.player().equals(p.getUUID())&&old.quest().equals(id)&&TreeQuestService.real(p)&&p.distanceToSqr(event.getPos().getX()+.5,event.getPos().getY()+.5,event.getPos().getZ()+.5)<=64&&PlacementProtection.check(p.serverLevel(),p,event.getPos(),event.getPos())==null){data.evidence().remove(site);data.setDirty();p.sendSystemMessage(Component.literal("Apiary supervision released. Previously earned work is preserved."));return;}assign(p,event.getPos());p.sendSystemMessage(Component.literal("Apiary supervision assigned to "+ApprovedProfessionContent.get(id).name()+". Remain within16blocks during real production; only this purpose receives new comb evidence."));}catch(RuntimeException e){p.sendSystemMessage(Component.literal(Objects.toString(e.getMessage(),"Apiary assignment refused; nothing consumed")));}}
 public static void assign(ServerPlayer p,net.minecraft.core.BlockPos pos){String id=p.getPersistentData().getString(TARGET);var level=p.serverLevel();if(!eligible(p,id)||level.dimension()!=net.minecraft.world.level.Level.OVERWORLD||!level.hasChunkAt(pos)||!level.getWorldBorder().isWithinBounds(pos)||p.distanceToSqr(pos.getX()+.5,pos.getY()+.5,pos.getZ()+.5)>64||PlacementProtection.check(level,p,pos,pos)!=null||!(level.getBlockEntity(pos) instanceof net.minecraft.world.level.block.entity.BeehiveBlockEntity hive)||!hive.getClass().getName().equals("cy.jdkdigital.productivebees.common.block.entity.AdvancedBeehiveBlockEntity"))throw new IllegalStateException("Crouch-right-click an accessible permitted native advanced hive with empty main hand after choosing this commission");if(FOREST.equals(id)){var audit=CommerceService.store(p.server).professionInspectionEvidence(p.getUUID(),ApiaryInspection.QUEST).orElseThrow(()->new IllegalStateException("Original documented apiary inspection is missing; restore matching records"));requireDocumentedSite(audit,level.dimension().location().toString(),pos);}
        var data=ApiaryJobsSavedData.get(p.server);data.evidence().assign(new ApiaryEvidence.Site(level.dimension().location().toString(),pos.asLong()),new ApiaryJobsEvidence.Job(p.getUUID(),id));data.setDirty();}
 static void requireDocumentedSite(String audit,String dimension,net.minecraft.core.BlockPos pos){try{var prefix=audit.substring(0,audit.indexOf(';'));var split=prefix.split("@",-1);var coordinates=split[1].split("\\s*,\\s*",-1);if(split.length!=2||coordinates.length!=3||!split[0].equals(dimension))throw new IllegalArgumentException();var center=new net.minecraft.core.BlockPos(Integer.parseInt(coordinates[0]),Integer.parseInt(coordinates[1]),Integer.parseInt(coordinates[2]));if(Math.abs((long)pos.getX()-center.getX())>8||Math.abs((long)pos.getY()-center.getY())>3||Math.abs((long)pos.getZ()-center.getZ())>8)throw new IllegalArgumentException();}catch(RuntimeException invalid){throw new IllegalStateException("Bind this forestry commission to a native hive inside your original documented apiary plot; unknown or moved site records grant no retrospective proof",invalid);}}
 public static void produced(BlockEntity hive,String species,int quantity){if(!(hive.getLevel() instanceof ServerLevel level))return;var data=ApiaryJobsSavedData.get(level.getServer());var site=new ApiaryEvidence.Site(level.dimension().location().toString(),hive.getBlockPos().asLong());var job=data.evidence().at(site).orElse(null);if(job==null)return;var p=level.getServer().getPlayerList().getPlayer(job.player());if(p==null||p.serverLevel()!=level||!level.getWorldBorder().isWithinBounds(hive.getBlockPos())||!eligible(p,job.quest())||p.distanceToSqr(hive.getBlockPos().getX()+.5,hive.getBlockPos().getY()+.5,hive.getBlockPos().getZ()+.5)>256||PlacementProtection.check(level,p,hive.getBlockPos(),hive.getBlockPos())!=null)return;data.evidence().record(site,job,species,quantity);data.setDirty();}
 public static Map<String,Integer> counts(ServerPlayer p,String id){return ApiaryJobsSavedData.get(p.server).evidence().counts(new ApiaryJobsEvidence.Job(p.getUUID(),id));}
 public static boolean ready(ServerPlayer p,String id){if(!eligible(p,id))return false;var counts=counts(p,id);var goals=CraftDeliveryRules.get(p.server).inputs(id);return FOREST.equals(id)?goals.entrySet().stream().allMatch(e->counts.getOrDefault(e.getKey(),0)>=e.getValue()):counts.values().stream().mapToInt(Integer::intValue).sum()>=goals.get("combs");}
 public static String status(ServerPlayer p,String id){return counts(p,id)+" supervised native combs; required "+CraftDeliveryRules.get(p.server).inputs(id)+". Choose this purpose at your resident, then crouch-right-click each permitted advanced hive with empty main hand. Remain within16blocks for actual iron/copper production; inactive, offline, remote and protected work does not count. Deliver the required real combs permanently; one native yield serves one supervisor/purpose. Crouch-right-click your same-purpose hive again to release supervision.";}
}
